"""Seating charts built from a roster."""

from typing import List

from rosterkit.models import Student


# ---
def seating_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """One line per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=lambda item: (item.last_name, item.first_name))
    return [_row_line(ordered, start, seats_per_row) for start in range(0, len(ordered), seats_per_row)]


def _row_line(ordered: List[Student], start: int, seats_per_row: int) -> str:
    names = [item.display_name for item in ordered[start:start + seats_per_row]]
    return f"Row {start // seats_per_row + 1}: " + " | ".join(names)

