# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _student(last, first):
    return Student("id-" + last, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        roster = [_student("Halloway", "Juno"), _student("Dunmere", "Piet"), _student("Zane", "Ola")]
        self.assertEqual(
            seating_rows(roster, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Zane, Ola"],
        )

    def test_bad_seat_counts_raise(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([_student("Zane", "Ola")], seats)

    def test_empty_roster_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
